export const add=(a,b)=>a.map((v,i)=>v+b[i]);
export const sub=(a,b)=>a.map((v,i)=>v-b[i]);
export const mul=(a,s)=>a.map(v=>v*s);
export const dot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
export const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
export const unit=a=>mul(a,1/(Math.hypot(...a)||1));
export const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
export const lerp=(a,b,t)=>a+(b-a)*t;
export function rotationMatrix(yaw,pitch){const cy=Math.cos(yaw),sy=Math.sin(yaw),cx=Math.cos(pitch),sx=Math.sin(pitch);return new Float32Array([cy,sx*sy,-cx*sy,0,0,cx,sx,0,sy,-sx*cy,cx*cy,0,0,0,0,1]);}
export function transform(m,p){return[m[0]*p[0]+m[4]*p[1]+m[8]*p[2],m[1]*p[0]+m[5]*p[1]+m[9]*p[2],m[2]*p[0]+m[6]*p[1]+m[10]*p[2]];}
export function inverseTransform(m,p){return[m[0]*p[0]+m[1]*p[1]+m[2]*p[2],m[4]*p[0]+m[5]*p[1]+m[6]*p[2],m[8]*p[0]+m[9]*p[1]+m[10]*p[2]];}
export function axisRotate(p,axis,angle){const c=Math.cos(angle),s=Math.sin(angle),v=dot(axis,p)*(1-c),q=cross(axis,p);return p.map((n,i)=>n*c+q[i]*s+axis[i]*v);}
export function perspective(aspect){const near=.002,far=100,f=1/Math.tan(Math.PI/9);return new Float32Array([f/aspect,0,0,0,0,f,0,0,0,0,(far+near)/(near-far),-1,0,0,2*far*near/(near-far),0]);}
export function fitDistance(bounds,target,yaw,pitch,aspect,margin=1.12){const m=rotationMatrix(yaw,pitch),tan=Math.tan(Math.PI/9);let d=.05;for(let mask=0;mask<8;mask++){const p=[0,1,2].map(i=>bounds[(mask>>i)&1][i]-target[i]),r=transform(m,p);d=Math.max(d,r[2]+margin*Math.max(Math.abs(r[0])/(tan*aspect),Math.abs(r[1])/tan));}return d;}
export function triangleMesh(){return {vertices:[],indices:[],mode:'triangles'};}
export function pushTriangle(mesh,a,b,c,normal,color,part=0){if(dot(cross(sub(b,a),sub(c,a)),normal)<0)[b,c]=[c,b];const i=mesh.vertices.length/10;for(const p of[a,b,c])mesh.vertices.push(...p,...normal,...color,part);mesh.indices.push(i,i+1,i+2);}
export function tube(mesh,a,b,r,color,segments=24){const axis=unit(sub(b,a)),u=unit(cross(axis,Math.abs(axis[1])<.9?[0,1,0]:[1,0,0])),v=cross(axis,u),r2=r*.81;const point=(base,rad,t)=>add(base,add(mul(u,rad*Math.cos(t)),mul(v,rad*Math.sin(t))));for(let i=0;i<segments;i++){const t0=i/segments*Math.PI*2,t1=(i+1)/segments*Math.PI*2,n0=add(mul(u,Math.cos(t0)),mul(v,Math.sin(t0))),n1=add(mul(u,Math.cos(t1)),mul(v,Math.sin(t1)));for(const [rad,inward]of[[r,false],[r2,true]]){const aa=point(a,rad,t0),ab=point(a,rad,t1),ba=point(b,rad,t0),bb=point(b,rad,t1),n=unit(add(n0,n1));pushTriangle(mesh,aa,ba,ab,mul(n,inward?-1:1),color);pushTriangle(mesh,ab,ba,bb,mul(n,inward?-1:1),color);}for(const [base,sign]of[[a,-1],[b,1]]){const aa=point(base,r,t0),ab=point(base,r,t1),ba=point(base,r2,t0),bb=point(base,r2,t1);pushTriangle(mesh,aa,ab,ba,mul(axis,sign),color);pushTriangle(mesh,ab,bb,ba,mul(axis,sign),color);}}}
export function polylineTube(mesh,points,r,color){for(let i=1;i<points.length;i++)tube(mesh,points[i-1],points[i],r,color);}
export function box(mesh,center,size,color,part=0){const p=[];for(let mask=0;mask<8;mask++)p.push(center.map((v,i)=>v+size[i]*(((mask>>i)&1)-.5)));for(const [a,b,c,d,n]of[[0,2,6,4,[-1,0,0]],[1,5,7,3,[1,0,0]],[0,4,5,1,[0,-1,0]],[2,3,7,6,[0,1,0]],[0,1,3,2,[0,0,-1]],[4,6,7,5,[0,0,1]]]){pushTriangle(mesh,p[a],p[b],p[c],n,color,part);pushTriangle(mesh,p[a],p[c],p[d],n,color,part);}}
export function lineMesh(segments,color=[.40,.59,.72]){const vertices=[];for(const pair of segments)for(const p of pair)vertices.push(...p,0,1,0,...color,0);return {vertices,indices:[],mode:'lines'};}
export function boxSegments(center,size){const p=[];for(let mask=0;mask<8;mask++)p.push(center.map((v,i)=>v+size[i]*(((mask>>i)&1)-.5)));const lines=[];for(let mask=0;mask<8;mask++)for(let i=0;i<3;i++)if(!((mask>>i)&1))lines.push([p[mask],p[mask|(1<<i)]]);return lines;}
export function routePoint(points,t){const lengths=points.slice(1).map((p,i)=>Math.hypot(...sub(p,points[i]))),total=lengths.reduce((a,b)=>a+b,0);let d=((t%1+1)%1)*total;for(let i=0;i<lengths.length;i++){if(d<=lengths[i]||i===lengths.length-1)return add(points[i],mul(sub(points[i+1],points[i]),d/lengths[i]));d-=lengths[i];}return points[0];}
export function rayTriangle(origin,direction,vertices,indices,stride=10,offset=[0,0,0]){let nearest=Infinity,index=-1;const ox=origin[0]-offset[0],oy=origin[1]-offset[1],oz=origin[2]-offset[2],dx=direction[0],dy=direction[1],dz=direction[2];for(let n=0;n<indices.length;n+=3){const a=indices[n]*stride,b=indices[n+1]*stride,c=indices[n+2]*stride;const e1x=vertices[b]-vertices[a],e1y=vertices[b+1]-vertices[a+1],e1z=vertices[b+2]-vertices[a+2],e2x=vertices[c]-vertices[a],e2y=vertices[c+1]-vertices[a+1],e2z=vertices[c+2]-vertices[a+2];const hx=dy*e2z-dz*e2y,hy=dz*e2x-dx*e2z,hz=dx*e2y-dy*e2x,det=e1x*hx+e1y*hy+e1z*hz;if(Math.abs(det)<1e-13)continue;const f=1/det,sx=ox-vertices[a],sy=oy-vertices[a+1],sz=oz-vertices[a+2],u=f*(sx*hx+sy*hy+sz*hz);if(u<0||u>1)continue;const qx=sy*e1z-sz*e1y,qy=sz*e1x-sx*e1z,qz=sx*e1y-sy*e1x,v=f*(dx*qx+dy*qy+dz*qz);if(v<0||u+v>1)continue;const t=f*(e2x*qx+e2y*qy+e2z*qz);if(t>0&&t<nearest){nearest=t;index=a;}}return{distance:nearest,index,part:index<0?null:Math.round(vertices[index+9]),point:Number.isFinite(nearest)?add(origin,mul(direction,nearest)):null};}

export function orthographic(aspect,halfHeight){const near=.002,far=100;return new Float32Array([1/(halfHeight*aspect),0,0,0,0,1/halfHeight,0,0,0,0,-2/(far-near),0,0,0,-(far+near)/(far-near),1]);}
export function fitOrthographicDistance(bounds,target,yaw,pitch,aspect,margin=1.1){const m=rotationMatrix(yaw,pitch),tan=Math.tan(Math.PI/9);let d=.05;for(let mask=0;mask<8;mask++){const p=[0,1,2].map(i=>bounds[(mask>>i)&1][i]-target[i]),r=transform(m,p);d=Math.max(d,margin*Math.abs(r[0])/(tan*aspect),margin*Math.abs(r[1])/tan,r[2]+.03);}return d;}
export function fitActualGeometry(objects,yaw,pitch,aspect,margin=1.14){const m=rotationMatrix(yaw,pitch),min=[Infinity,Infinity,Infinity],max=[-Infinity,-Infinity,-Infinity],rotated=[];for(const obj of objects){const off=obj.offset||[0,0,0];for(let i=0;i<obj.vertices.length;i+=10){const q=transform(m,[obj.vertices[i]+off[0],obj.vertices[i+1]+off[1],obj.vertices[i+2]+off[2]]);rotated.push(q);for(let k=0;k<3;k++){min[k]=Math.min(min[k],q[k]);max[k]=Math.max(max[k],q[k]);}}}const center=min.map((v,i)=>(v+max[i])/2),target=inverseTransform(m,center),tan=Math.tan(Math.PI/9);let distance=.05;for(const p of rotated){const q=sub(p,center);distance=Math.max(distance,q[2]+margin*Math.max(Math.abs(q[0])/(tan*aspect),Math.abs(q[1])/tan));}return{target,distance};}
